intro.body:
下面是模型 Mock 和工具 Mock 的核心。`MockLLM` 按关键词命中预设响应并记账，`MockToolbox` 能注册工具、也能 `block` 危险工具。

```python
class MockLLM:
    def __init__(self, responses=None):
        self.responses = responses or {}
        self.call_log = []
        self._default = "This is a mock response."
    def complete(self, prompt, **kwargs):
        self.call_log.append({"prompt": prompt, **kwargs})
        for pattern, resp in self.responses.items():
            if pattern in prompt:
                return resp
        return self._default
class MockToolbox:
    def __init__(self):
        self.tools = {}
        self.call_history = []
        self._blocked = set()
    def block(self, name):
        self._blocked.add(name)
    def execute(self, name, **kwargs):
        if name in self._blocked:
            raise PermissionError(f"Tool '{name}' is blocked in test")
        self.call_history.append({"tool": name, **kwargs})
        return self.tools.get(name, lambda **k: {"status": "mock_success"})(**kwargs)
```

没有约束的 agent 会陷进「再搜一次 → 还不够 → 再搜一次」的死循环，每一圈都是一次 LLM 调用，都在烧钱。所以要在 harness 层强制多维度上限——不靠开发者自觉。

```python
class ExecutionGuard:
    def __init__(self, limits):
        self.limits = limits
        self.steps = 0
        self.llm_calls = 0
        self.cost_usd = 0.0
        self.start = time.time()
    def check(self, event_type, tokens=0):
        self.steps += 1
        if event_type == "llm_call":
            self.llm_calls += 1
            self.cost_usd += tokens * 0.00001
        violations = []
        if self.steps > self.limits.max_steps:
            violations.append("steps")
        if self.cost_usd > self.limits.max_cost_usd:
            violations.append("cost")
        if time.time() - self.start > self.limits.max_wall_time_seconds:
            violations.append("time")
        if violations:
            raise ResourceExhaustedError(", ".join(violations))
```

评估用例（`EvalCase`）和指标（`EvalMetric`，每个带 scorer 和阈值）先定义好，harness 跑模型、逐用例打分、再聚合，最后用门禁判断是否全部达标。

```python
class TDFEvalHarness:
    def __init__(self):
        self.cases = []
        self.metrics = []
    def add_cases(self, cases):
        self.cases.extend(cases)
    def add_metric(self, metric):
        self.metrics.append(metric)
    def evaluate(self, model_fn):
        results = []
        for case in self.cases:
            output = model_fn(case.input_text)
            scores = {m.name: m.scorer(output, case) for m in self.metrics}
            results.append({"category": case.category, "scores": scores})
        return self._aggregate(results)
    def _aggregate(self, results):
        summary = {}
        for m in self.metrics:
            vals = [r["scores"][m.name] for r in results]
            avg = sum(vals) / len(vals) if vals else 0
            summary[m.name] = {"mean": round(avg, 4), "passed": avg >= m.threshold}
        summary["_overall"] = {"passed": all(s["passed"] for s in summary.values())}
        return summary
    def gate_check(self, results):
        return results.get("_overall", {}).get("passed", False)
```

训练时最危险的错觉是「loss 在降，模型在变好」。实际可能是 training loss 一路往下、eval score 却先升后降——这就是**过拟合**，模型在训练集上越背越熟，在评估集上反而开始退化。光看 loss 看不出来，必须在训练中周期性地用评估 harness 跑 checkpoint：每隔 N 步评一次、记录历史、追踪「最佳 checkpoint」、综合分连续下降时打退化警告、并支持 early stopping。所以最终发布的往往不是最后一个 checkpoint，而是评估分最高的那个。

```python
class CheckpointEvalHarness:
    def __init__(self, eval_harness, eval_every=500):
        self.eval = eval_harness
        self.eval_every = eval_every
        self.history = []
        self._best_score = 0.0
        self._best_step = None
    def on_checkpoint(self, step, model_fn):
        if step % self.eval_every != 0:
            return {}
        results = self.eval.evaluate(model_fn)
        means = [v["mean"] for k, v in results.items() if k != "_overall"]
        overall = sum(means) / len(means) if means else 0
        record = {"step": step, "overall_score": round(overall, 4)}
        if overall > self._best_score:
            self._best_score, self._best_step = overall, step
            record["is_best"] = True
        self.history.append(record)
        recent = [h["overall_score"] for h in self.history[-3:]]
        if len(recent) == 3 and recent[0] > recent[1] > recent[2]:
            record["warning"] = "DEGRADATION_DETECTED"
        return record
```

逐条规则比对 baseline 与 current，按方向算回归比例，再结合绝对下限和 severity 判定是否放行。

```python
class QualityGate:
    def __init__(self, rules):
        self.rules = rules
    def check(self, baseline, current):
        results, all_passed = {}, True
        for rule in self.rules:
            b, c = baseline.get(rule.metric, 0), current.get(rule.metric, 0)
            if rule.direction == "higher_is_better":
                regression = (b - c) / b if b else 0
                below_min = c < rule.absolute_minimum
            else:
                regression = (c - b) / b if b else 0
                below_min = c > rule.absolute_minimum
            passed = regression <= rule.max_regression and not below_min
            if not passed and rule.severity == "error":
                all_passed = False
            results[rule.metric] = {"regression": round(regression, 4), "passed": passed}
        return {"passed": all_passed, "details": results}
```

`PropertyChecker` 支持链式注册多条属性，逐条执行并兜住异常，最后聚合成是否全过。属性本身是一组可复用的小函数。

```python
class PropertyChecker:
    def __init__(self):
        self.checks = []
    def add(self, name, fn):
        self.checks.append((name, fn))
        return self
    def verify(self, output):
        results = {}
        for name, fn in self.checks:
            try:
                results[name] = {"passed": fn(output)}
            except Exception as e:
                results[name] = {"passed": False, "error": str(e)}
        all_passed = all(r["passed"] for r in results.values())
        return {"passed": all_passed, "checks": results}
checker = (PropertyChecker()
    .add("not_too_short", lambda o: len(o) >= 10)
    .add("not_too_long", lambda o: len(o) <= 500)
    .add("contains_topic", lambda o: "量子" in o)
    .add("no_hallucination", lambda o: "据报道" not in o))
result = checker.verify("量子计算是利用量子力学原理进行计算的新型范式。")
```
